mapper.select:
select 
from spot_reservation_order
where 1 = 1
and scenic_area_id = #{scenicAreaId}
and spot_id = #{spotId}
and user_id = #{userId}
and visit_date = #{visitDate}
and status = #{status}
and source_type = #{sourceType}
and reservation_no = #{reservationNo}
order by create_time desc, id desc

select
    count(1) as orderCount,
    coalesce(sum(visitor_count), 0) as visitorCount
from spot_reservation_order
where visit_date = #{visitDate}
and scenic_area_id = #{scenicAreaId}

select 
from spot_reservation_order
where 1 = 1
and scenic_area_id = #{scenicAreaId}
order by coalesce(cancel_time, create_time) desc, id desc
limit #{limit}
